"""Static forms for the self-contained advisory edition. No runtime dependency."""
from html import escape as e
def field(id, label, value='', note='', text=False, placeholder=''):
    return f'<div class="field"><label for="{id}">{label}</label><input data-advice id="{id}" {"maxlength=500" if text else "inputmode=decimal"} value="{e(str(value))}" placeholder="{e(placeholder)}">'+(f'<small>{note}</small>' if note else '')+'</div>'
def select(id,label,options,note=''):
    return f'<div class="field"><label for="{id}">{label}</label><select data-advice id="{id}">'+''.join(f'<option value="{v}">{s}</option>' for v,s in options)+(f'</select><small>{note}</small>' if note else '</select>')+'</div>'
def check(id,label):
    return f'<label class="check"><input data-advice type="checkbox" id="{id}"> {label}</label>'
def area(id,label,placeholder='',limit=900):
    return f'<div class="field"><label for="{id}">{label}</label><textarea data-advice id="{id}" rows="3" maxlength="{limit}" placeholder="{e(placeholder)}"></textarea></div>'
def grid(*args): return '<div class="ad-grid">'+''.join(args)+'</div>'
def card(n,title,body): return f'<article class="glass"><div class="ad-section"><span>{n}</span><h2>{title}</h2></div>{body}</article>'
